    class CameraRig {
      constructor(camera, domElement) {
        this.camera = camera;
        this.domElement = domElement;

        this.target = new THREE.Vector3(0, 1.1, -0.2);
        this.goalTarget = this.target.clone();

        this.spherical = new THREE.Spherical(17, 1.12, 2.55);
        this.goalSpherical = this.spherical.clone();

        this.dragging = false;
        this.lastX = 0;
        this.lastY = 0;
        this.autoRotate = false;

        this.bindEvents();
        this.update(0.016);
      }

      bindEvents() {
        this.domElement.addEventListener("pointerdown", (event) => {
          this.dragging = true;
          this.lastX = event.clientX;
          this.lastY = event.clientY;
          this.domElement.setPointerCapture(event.pointerId);
          this.domElement.classList.add("dragging");
        });

        this.domElement.addEventListener("pointermove", (event) => {
          if (!this.dragging) return;

          const dx = event.clientX - this.lastX;
          const dy = event.clientY - this.lastY;

          this.lastX = event.clientX;
          this.lastY = event.clientY;

          this.goalSpherical.theta -= dx * 0.006;
          this.goalSpherical.phi -= dy * 0.005;
          this.goalSpherical.phi = THREE.MathUtils.clamp(
            this.goalSpherical.phi,
            0.16,
            1.48
          );
        });

        const endDrag = (event) => {
          this.dragging = false;
          this.domElement.classList.remove("dragging");

          if (event.pointerId !== undefined &&
              this.domElement.hasPointerCapture(event.pointerId)) {
            this.domElement.releasePointerCapture(event.pointerId);
          }
        };

        this.domElement.addEventListener("pointerup", endDrag);
        this.domElement.addEventListener("pointercancel", endDrag);

        this.domElement.addEventListener(
          "wheel",
          (event) => {
            event.preventDefault();
            this.goalSpherical.radius *= Math.exp(event.deltaY * 0.001);
            this.goalSpherical.radius = THREE.MathUtils.clamp(
              this.goalSpherical.radius,
              7,
              36
            );
          },
          { passive: false }
        );

        this.domElement.addEventListener("dblclick", () => {
          this.setView("orbit");
        });
      }

      setView(name) {
        const views = {
          orbit: {
            target: new THREE.Vector3(0, 1.1, -0.2),
            spherical: new THREE.Spherical(17, 1.12, 2.55)
          },
          stern: {
            target: new THREE.Vector3(0, 1.35, -2.6),
            spherical: new THREE.Spherical(14.5, 1.16, 2.62)
          },
          deck: {
            target: new THREE.Vector3(0, 1.1, 1.25),
            spherical: new THREE.Spherical(10.8, 1.34, 2.3)
          },
          top: {
            target: new THREE.Vector3(0, 0, 0),
            spherical: new THREE.Spherical(18, 0.18, 0.05)
          }
        };

        const view = views[name];
        if (!view) return;

        this.goalTarget.copy(view.target);
        this.goalSpherical.copy(view.spherical);

        document.querySelectorAll("[data-view]").forEach((button) => {
          button.classList.toggle("active", button.dataset.view === name);
        });
      }

      update(delta) {
        if (this.autoRotate && !this.dragging) {
          this.goalSpherical.theta += delta * 0.085;
        }

        const smoothing = 1 - Math.exp(-7 * delta);
        this.spherical.radius = THREE.MathUtils.lerp(
          this.spherical.radius,
          this.goalSpherical.radius,
          smoothing
        );
        this.spherical.theta = THREE.MathUtils.lerp(
          this.spherical.theta,
          this.goalSpherical.theta,
          smoothing
        );
        this.spherical.phi = THREE.MathUtils.lerp(
          this.spherical.phi,
          this.goalSpherical.phi,
          smoothing
        );
        this.target.lerp(this.goalTarget, smoothing);

        this.spherical.makeSafe();

        this.camera.position
          .setFromSpherical(this.spherical)
          .add(this.target);

        this.camera.lookAt(this.target);
      }
    }

