    let frame = 0;

    function animate() {
      const delta = Math.min(clock.getDelta(), 0.05);
      const elapsed = clock.elapsedTime;

      cameraRig.update(delta);

      // Gentle vessel motion.
      boat.position.y = 0.08 + Math.sin(elapsed * 0.72) * 0.035;
      boat.rotation.z = Math.sin(elapsed * 0.58) * 0.006;
      boat.rotation.x = Math.sin(elapsed * 0.46) * 0.004;

      // Crane hoisting and lowering cycle.
      const cranePhase = elapsed * 0.72;
      const hookHeight = 2.12 + Math.sin(cranePhase) * 0.48;

      hookGroup.position.set(0, hookHeight, -4.55);
      workingBuoy.position.set(0, hookHeight - 0.9, -4.55);
      workingBuoy.rotation.z = Math.sin(cranePhase) * 0.08;

      updateCylinderBetween(
        hoistCable,
        new THREE.Vector3(0, 4.18, -4.62),
        new THREE.Vector3(0, hookHeight, -4.55)
      );

      radar.rotation.y = elapsed * 0.55;

      // Water surface animation.
      const positions = waterGeometry.attributes.position;

      for (let i = 0; i < positions.count; i++) {
        const x = positions.getX(i);
        const z = positions.getZ(i);

        const wave =
          Math.sin(x * 0.19 + elapsed * 0.8) * 0.075 +
          Math.sin(z * 0.27 - elapsed * 0.62) * 0.055 +
          Math.sin((x + z) * 0.43 + elapsed * 0.9) * 0.025;

        positions.setY(i, wave);
      }

      positions.needsUpdate = true;

      if (frame % 3 === 0) {
        waterGeometry.computeVertexNormals();
      }

      // Distant buoy bob.
      distantBuoy.position.y = Math.sin(elapsed * 0.7) * 0.045;

      positionLabel(craneLabel, hookGroup);
      positionLabel(deckLabel, boat);

      renderer.render(scene, camera);
      frame++;
    }

    renderer.setAnimationLoop(animate);

    requestAnimationFrame(() => {
      document.getElementById("loading").classList.add("hidden");
    });
